package com.morongaming.forsakenrealm;
import android.content.Context;import android.graphics.*;import android.view.*;import org.json.*;
/** Local plan canvas. Server validates the full footprint again at purchase. */
final class HousingView extends View {
 interface Host{JSONObject state();void send(JSONObject command);void close();String status();}
 private final Host host;private final JSONObject design;private final Paint p=new Paint(3);private float x,y,cx,cy;private int rotation;private final RectF area=new RectF();
 HousingView(Context c,JSONObject d,Host h){super(c);design=d;host=h;JSONObject me=h.state().optJSONObject("you");cx=(float)me.optDouble("x");cy=(float)me.optDouble("y");x=cx+180;y=cy;}
 private float sx(float value){return area.centerX()+(value-cx)*area.width()/700;}
 private float sy(float value){return area.centerY()+(value-cy)*area.width()/700;}
 private JSONObject preview(){JSONObject h=host.state().optJSONObject("housing");return h==null?null:h.optJSONObject("preview");}
 private boolean matches(JSONObject q){return q!=null&&q.optString("design").equals(design.optString("id"))&&Math.abs(q.optDouble("x")-x)<1&&Math.abs(q.optDouble("y")-y)<1&&q.optInt("rotation")==rotation;}
 protected void onDraw(Canvas c){super.onDraw(c);float w=getWidth(),h=getHeight(),u=Math.min(w/900,h/520);ReferenceSkin.get(getContext());MenuArt.get(getContext()).backdrop(c);p.setColor(0xffefddb7);p.setTypeface(Typeface.create(Typeface.SERIF,Typeface.NORMAL));p.setTextSize(22*u);c.drawText(design.optString("name")+" • matching house deed required",20*u,32*u,p);p.setTextSize(14*u);c.drawText("Tap nearby land • rotate • check site • confirm deed use",20*u,57*u,p);
 area.set(20*u,75*u,w-20*u,h-110*u);c.save();c.clipRect(area);p.setColor(0xff354939);c.drawRect(area,p);
 JSONArray buildings=host.state().optJSONArray("mapBuildings");if(buildings!=null)for(int i=0;i<buildings.length();i++){JSONObject b=buildings.optJSONObject(i);p.setColor(0xff86725a);c.drawRect(sx((float)(b.optDouble("x")-b.optDouble("halfWidth"))),sy((float)(b.optDouble("y")-b.optDouble("depth"))),sx((float)(b.optDouble("x")+b.optDouble("halfWidth"))),sy((float)b.optDouble("y")+10),p);}
 JSONObject map=host.state().optJSONObject("worldMap");if(map!=null)for(String key:new String[]{"roads","paths","streams"}){JSONArray lines=map.optJSONArray(key);if(lines!=null)for(int i=0;i<lines.length();i++){JSONObject line=lines.optJSONObject(i);JSONArray pts=line.optJSONArray("points");if(pts==null)continue;p.setColor(key.equals("streams")?0xff6195a2:0xffaa9671);p.setStrokeWidth((float)line.optDouble("width",20)*area.width()/700);for(int j=1;j<pts.length();j++){JSONObject a=pts.optJSONObject(j-1),b=pts.optJSONObject(j);c.drawLine(sx((float)a.optDouble("x")),sy((float)a.optDouble("y")),sx((float)b.optDouble("x")),sy((float)b.optDouble("y")),p);}}}
 JSONArray resources=host.state().optJSONArray("resources");if(resources!=null)for(int i=0;i<resources.length();i++){JSONObject r=resources.optJSONObject(i);p.setColor(0xff547348);c.drawCircle(sx((float)r.optDouble("x")),sy((float)r.optDouble("y")),5*u,p);}
 float dw=(float)design.optDouble(rotation%180==0?"width":"depth"),dh=(float)design.optDouble(rotation%180==0?"depth":"width");p.setColor(matches(preview())?0xaa78bb78:0xaad7b45f);c.drawRect(sx(x-dw/2),sy(y-dh/2),sx(x+dw/2),sy(y+dh/2),p);p.setColor(Color.WHITE);c.drawCircle(sx(cx),sy(cy),5*u,p);p.setTextSize(13*u);c.drawText("YOU",sx(cx)+8*u,sy(cy),p);c.restore();
 p.setColor(0xffeee0c2);p.setTextSize(15*u);c.drawText("CLOSE",20*u,h-25*u,p);c.drawText("ROTATE "+rotation+"°",w*.23f,h-25*u,p);c.drawText("CHECK SITE",w*.49f,h-25*u,p);p.setColor(matches(preview())?0xffa6e5a3:0xff777d77);c.drawText("BUY",w*.81f,h-25*u,p);p.setColor(0xffe8d9b9);p.setTextSize(13*u);c.drawText(host.status(),20*u,h-75*u,p);c.drawText("One property • no protection • 90-day relocation lock",20*u,h-53*u,p);
 }
 public boolean onTouchEvent(MotionEvent e){if(e.getAction()!=MotionEvent.ACTION_UP)return true;try{if(area.contains(e.getX(),e.getY())){x=cx+(e.getX()-area.centerX())*700/area.width();y=cy+(e.getY()-area.centerY())*700/area.width();}else if(e.getY()>getHeight()-55* Math.min(getWidth()/900f,getHeight()/520f)){float part=e.getX()/getWidth();if(part<.2){host.close();return true;}else if(part<.46)rotation=(rotation+90)%360;else if(part<.78)host.send(new JSONObject().put("type","housingPreview").put("design",design.optString("id")).put("x",x).put("y",y).put("rotation",rotation));else if(matches(preview()))new android.app.AlertDialog.Builder(getContext()).setTitle("Claim "+design.optString("name")+"?").setMessage("Consumes your matching house deed. This uses your one property allowance and starts the 90-day relocation lock.").setPositiveButton("Use deed",(d,n)->{try{host.send(new JSONObject().put("type","housingConfirm").put("nonce",preview().optString("nonce")));}catch(Exception ignored){}}).setNegativeButton("Cancel",null).show();}invalidate();}catch(Exception ignored){}return true;}
}

